import {turningToRef} from '../../src/core/build/joint-state.ts';
import {forceVelocityFactor} from '../../src/core/muscle/force-velocity.ts';
import {Vector3,Quaternion} from '@babylonjs/core/Maths/math.vector.js';
import {contactEffort} from '../../research/stand-up-contact-effort.mjs';
export function contactPolicy({model,parameters:p}){
 const state={phase:'static hold',saturated:0,torque:[]};const turning=[];
 const policy=o=>{
  let feed=p.torques;
  if(p.recompute){
   const patches=p.forces.map(f=>{const s=o.segments.find(s=>s.name===f.segment);return {kind:'point',at:new Vector3(...f.local).applyRotationQuaternionToRef(new Quaternion(...s.rotation),new Vector3()).addInPlaceFromFloats(...s.position)};});
   const e=contactEffort(model,o,patches,p.forces.map(f=>f.segment),p.targets,{poseGain:0,poseDamping:0});
   feed=Array.from(e.t0,(v,i)=>(v-p.forces.reduce((sum,f,k)=>sum+f.force.reduce((n,x,j)=>n+e.C[i*6*p.forces.length+6*k+j]*x,0),0))/e.scales[i]);
  }
  const velocity=[],activation=[];let first=0;state.saturated=0;
  for(const joint of model.joints){const angles=o.joints.slice(first,first+joint.dofs.length).map(j=>j.angle);turningToRef(joint,angles,turning);
   for(let k=0;k<joint.dofs.length;k++){
    const i=first+k,c=model.channels[i],obs=o.joints[i],peak=Math.min(c.positive.peak,c.negative.peak);
    const error=turning[k].reduce((n,v,j)=>n+v*(p.targets[first+j]-angles[j]),0);
    const torque=p.feedforward*feed[i]+peak*(p.gain*error-p.damping*obs.speed),side=torque>=0?c.positive:c.negative;
    const capacity=side.peak*forceVelocityFactor((torque>=0?1:-1)*obs.speed,side.curve);
    state.torque[i]=torque;activation[i]=capacity>0?Math.min(1,Math.abs(torque)/capacity):0;velocity[i]=torque>0?'+inf':torque<0?'-inf':0;
    if(activation[i]===1)state.saturated++;
   }first+=joint.dofs.length;
  }
  return {kind:'muscles',velocity,activation,handPoses:{left:'open',right:'open'}};
 };policy.state=state;return policy;
}
